package mz.bam.seeky.android;
import android.app.*;import android.content.*;import android.content.pm.*;import android.database.*;import android.net.Uri;import android.os.*;import android.provider.OpenableColumns;import java.io.*;import java.nio.file.*;import java.util.*;import java.util.concurrent.*;import java.util.concurrent.atomic.*;
import org.junit.*;import org.junit.runner.RunWith;import org.robolectric.*;import org.robolectric.annotation.*;import org.robolectric.shadows.*;import static org.junit.Assert.*;import static org.robolectric.Shadows.shadowOf;
@RunWith(RobolectricTestRunner.class) @Config(manifest=Config.NONE,sdk=33,application=Application.class) @LooperMode(LooperMode.Mode.PAUSED)
public class StudyImportTest {
 Application app;StudyStore store;
 public static class Source extends ContentProvider {
  public boolean onCreate(){return true;}public String getType(Uri u){return u.getLastPathSegment().equals("bad")?"application/octet-stream":"text/plain";}
  public Cursor query(Uri u,String[] p,String s,String[] a,String o){String id=u.getLastPathSegment();MatrixCursor c=new MatrixCursor(new String[]{OpenableColumns.DISPLAY_NAME});c.addRow(new Object[]{"Livro "+id+(id.equals("bad")?".exe":".txt")});return c;}
  public ParcelFileDescriptor openFile(Uri u,String mode)throws FileNotFoundException{String id=u.getLastPathSegment();if(id.equals("missing"))throw new FileNotFoundException("Ficheiro inacessível.");File file=new File(getContext().getCacheDir(),"import-source.txt");try{Files.write(file.toPath(),id.equals("empty")?new byte[0]:("Livro completo, conteúdo diferente: "+(id.equals("same")?"0":id)).getBytes("UTF-8"));}catch(IOException e){throw new FileNotFoundException();}return ParcelFileDescriptor.open(file,ParcelFileDescriptor.MODE_READ_ONLY);}
  public Uri insert(Uri u,ContentValues v){return null;}public int update(Uri u,ContentValues v,String s,String[] a){return 0;}public int delete(Uri u,String s,String[] a){return 0;}
 }
 @Before public void setup(){app=RuntimeEnvironment.getApplication();Source provider=new Source();ProviderInfo pi=new ProviderInfo();pi.authority="seeky.import.test";provider.attachInfo(app,pi);ShadowContentResolver.registerProviderInternal(pi.authority,provider);store=new StudyStore(app);}
 @After public void close(){store.close();}
 Uri uri(String id){return Uri.parse("content://seeky.import.test/book/"+id);}
 Intent selected(int n){ClipData clip=ClipData.newRawUri("books",uri("0"));for(int i=1;i<n;i++)clip.addItem(new ClipData.Item(uri(""+i)));Intent result=new Intent();result.setClipData(clip);return result;}
 StudyImporter.Result run(List<Uri> files)throws Exception{return StudyImporter.run(app,store,files,0,true,()->false,(r,n)->{});}
 @Test public void all1205SelectedBooksAreImportedAndSelectingAgainSkipsExistingCopies()throws Exception{List<Uri> files=StudyImporter.selected(selected(1205));assertEquals(1205,files.size());StudyImporter.Result r=run(files);assertEquals(1205,r.imported);assertEquals(1205,r.processed());assertEquals(0,r.failed);assertEquals(0,r.remaining());assertEquals(1205,store.count("materials",null,null));assertEquals(1,store.count("materials","name=?",new String[]{"Livro 1204.txt"}));StudyImporter.Result retry=run(files);assertEquals(0,retry.imported);assertEquals(1205,retry.duplicates);assertEquals(1205,store.count("materials",null,null));assertEquals(1205,StudyFileProvider.directory(app).listFiles().length);for(File f:StudyFileProvider.directory(app).listFiles())assertFalse(f.getName().endsWith(".part"));String report=new String(Files.readAllBytes(r.report.toPath()),"UTF-8");assertTrue(report.contains("Livro 1204.txt"));assertEquals(0,retry.failed);}
 @Test public void inaccessibleEmptyAndUnsupportedFilesDoNotHideLaterBooks()throws Exception{StudyImporter.Result r=run(Arrays.asList(uri("0"),uri("missing"),uri("empty"),uri("bad"),uri("1")));assertEquals(2,r.imported);assertEquals(3,r.failed);assertEquals(5,r.processed());assertEquals(0,r.remaining());String report=new String(Files.readAllBytes(r.report.toPath()),"UTF-8");assertTrue(report.contains("Livro missing.txt"));assertTrue(report.contains("Material vazio"));assertTrue(report.contains("Livro bad.exe"));assertEquals(2,store.count("materials",null,null));}
 @Test public void cancelRetainsCompletedBooksAndReselectionImportsOnlyRemainingOnes()throws Exception{List<Uri> files=StudyImporter.selected(selected(20));AtomicBoolean stop=new AtomicBoolean();StudyImporter.Result r=StudyImporter.run(app,store,files,0,true,stop::get,(state,name)->{if(state.imported==3)stop.set(true);});assertTrue(r.cancelled);assertEquals(3,r.imported);assertEquals(17,r.remaining());StudyImporter.Result retry=run(files);assertEquals(17,retry.imported);assertEquals(3,retry.duplicates);assertEquals(20,store.count("materials",null,null));}
 @Test public void duplicatesUseContentAndDestinationNotJustSameTitle()throws Exception{StudyImporter.Result r=run(Arrays.asList(uri("0"),uri("same")));assertEquals(1,r.imported);assertEquals(1,r.duplicates);long subject=store.save("subjects",0,StudyStore.values("title","Módulo","color",0,"created",1));StudyImporter.Result grouped=StudyImporter.run(app,store,Arrays.asList(uri("0")),subject,true,()->false,(state,name)->{});assertEquals(1,grouped.imported);assertEquals(2,store.count("materials",null,null));}
 @Test public void visibleBookImportUsesTheWholeSelectionAndOffersTheCompleteReport()throws Exception{MainActivity a=Robolectric.buildActivity(MainActivity.class).get();a.setTheme(android.R.style.Theme_Material_NoActionBar);a.prefs=a.getSharedPreferences("seeky",0);a.colors();a.tab="Livros";a.studies=new StudyHub(a);a.books=new BookLibrary(a);try(WorkTestSupport work=new WorkTestSupport()){a.studies.imported(selected(75),true);PlusUi.WORK.submit(()->{}).get(60,TimeUnit.SECONDS);shadowOf(Looper.getMainLooper()).idle();String id;try(TaskStore db=new TaskStore(a)){id=db.jobs(0,1).get(0).s("id");}work.run(id);try(TaskStore db=new TaskStore(a)){ImportReport.save(a,db,id);}assertEquals(75,store.count("materials",null,null));String summary=a.studies.prefs.getString("import_summary","");assertTrue(summary.contains("75 importados"));assertTrue(summary.contains("75 seleccionados"));org.robolectric.android.controller.ActivityController<TaskActivity> tasks=Robolectric.buildActivity(TaskActivity.class).create().start().resume().visible();try(TaskStore db=new TaskStore(a)){tasks.get().menu(db.job(id));assertTrue(BooksToolsTest.labels(org.robolectric.shadows.ShadowDialog.getLatestDialog().getWindow().getDecorView()).contains("Guardar relatório CSV"));}finally{tasks.pause().stop().destroy();}}finally{UiDialog.dismissAll(a);a.studies.close();a.books.close();a.dead=true;a.worker.shutdown();a.finder.shutdown();a.searchJobs.close();}}
 @Test public void storedHashAloneCannotCauseAnAlteredExistingBookToBeSkipped()throws Exception{run(Arrays.asList(uri("0")));StudyStore.Row row=store.rows("materials",null,null,null,1).get(0);Files.write(new File(row.s("path")).toPath(),"Changed content".getBytes("UTF-8"));StudyImporter.Result result=run(Arrays.asList(uri("0")));assertEquals(0,result.duplicates);assertEquals(1,result.failed);assertTrue(result.summary().contains("alterada"));assertEquals(1,store.count("materials",null,null));}
 @Test public void pickerSingleDataAndUnreadableItemsAreCountedWithoutTruncation()throws Exception{assertEquals(1,StudyImporter.selected(new Intent().setData(uri("a"))).size());ClipData clip=ClipData.newPlainText("invalid","no document URI");clip.addItem(new ClipData.Item(uri("last")));Intent selection=new Intent();selection.setClipData(clip);StudyImporter.Result r=run(StudyImporter.selected(selection));assertEquals(2,r.selected);assertEquals(1,r.failed);assertEquals(1,r.imported);}
}
